<template>
  <section class="teacher-page" data-testid="teacher-student-profile-page">
    <div v-if="store.profileState === 'LOADING' || store.profileState === 'INITIAL'" class="state-panel">正在加载学生画像...</div>
    <div v-else-if="store.profileState !== 'READY' || !store.profile" class="state-panel state-panel--error"><h1>{{ store.profileState === 'FORBIDDEN' ? '当前账号没有访问权限' : '学生画像暂时不可用' }}</h1><p>{{ store.error ?? '请确认学生与课程仍然存在。' }}</p><button type="button" @click="load">重新加载</button></div>
    <template v-else><header class="page-heading"><div><p class="eyebrow">Student evidence</p><h1>{{ profile.student.displayName }}</h1><p>{{ profile.student.courseName }} · {{ profile.student.className }}</p></div><button class="outline-button" type="button" @click="router.push('/teacher/workbench')">返回工作台</button></header><section class="fact-banner"><div><span>当前课程</span><strong>{{ profile.student.courseName }}</strong></div><div><span>所属班级</span><strong>{{ profile.student.className }}</strong></div><div><span>学习记录</span><strong>{{ profile.recentAttempts.length }} 条</strong></div></section><div class="profile-grid"><main class="main-column"><section class="panel"><header class="panel-heading"><div><span class="eyebrow">Learning state</span><h2>当前学习状态</h2></div></header><template v-if="profile.learningState"><div class="state-metrics"><div><span>知识点</span><strong>{{ profile.learningState.knowledgePointName }}</strong></div><div><span>掌握度</span><strong>{{ percent(profile.learningState.mastery) }}</strong></div><div><span>置信度</span><strong>{{ percent(profile.learningState.confidence) }}</strong></div><div><span>遗忘风险</span><strong>{{ percent(profile.learningState.forgettingRisk) }}</strong></div></div></template><p v-else class="empty-inline">暂无学习状态数据</p></section><section class="panel"><header class="panel-heading"><div><span class="eyebrow">Recent attempts</span><h2>最近答题记录</h2></div><span class="panel-count">{{ profile.recentAttempts.length }} 条</span></header><div v-if="profile.recentAttempts.length" class="attempt-list"><article v-for="attempt in profile.recentAttempts" :key="`${attempt.questionId}-${attempt.attemptTime}`"><span class="result-dot" :class="attempt.correct ? 'is-correct' : 'is-wrong'">{{ attempt.correct ? '对' : '错' }}</span><div><strong>{{ attempt.knowledgePointName }}</strong><p>{{ attempt.questionSummary }}</p><small>{{ formatDate(attempt.attemptTime) }} · 用时 {{ attempt.durationSeconds }} 秒</small></div></article></div><p v-else class="empty-inline">暂无答题记录</p></section></main><aside class="side-column"><section class="panel"><header class="panel-heading"><div><span class="eyebrow">Diagnosis</span><h2>诊断摘要</h2></div></header><template v-if="profile.diagnosis"><p class="hypothesis">{{ profile.diagnosis.primaryHypothesis }}</p><div class="diagnosis-meta"><span :class="`severity severity--${profile.diagnosis.severity.toLowerCase()}`">{{ severityLabel(profile.diagnosis.severity) }}</span><span>置信度 {{ percent(profile.diagnosis.confidence) }}</span></div><RouterLink v-if="caseId" class="text-link" :to="`/teacher/diagnosis-cases/${encodeURIComponent(caseId)}`">查看诊断证据 →</RouterLink></template><p v-else class="empty-inline">暂无可用诊断证据</p></section><section class="panel"><header class="panel-heading"><div><span class="eyebrow">Intervention</span><h2>干预状态</h2></div></header><template v-if="profile.intervention"><dl class="facts"><div><dt>策略</dt><dd>{{ profile.intervention.strategy }}</dd></div><div><dt>状态</dt><dd>{{ profile.intervention.status }}</dd></div><div v-if="profile.intervention.assignmentStatus"><dt>任务</dt><dd>{{ profile.intervention.assignmentStatus }}</dd></div><div v-if="profile.intervention.transferValidation"><dt>迁移验证</dt><dd>{{ profile.intervention.transferValidation }}</dd></div></dl><p class="rationale">{{ profile.intervention.teacherRationale }}</p></template><p v-else class="empty-inline">暂无干预记录</p></section></aside></div></template>
  </section>
</template>
<script setup lang="ts">
import { computed, onMounted } from 'vue'; import { RouterLink, useRoute, useRouter } from 'vue-router'; import { useTeacherStore } from '@/stores/teacherStore'; import { teacherStatusLabel, teacherStrategyLabel, teacherTimestampLabel } from '@/adapters/teacher/presentation'
const route=useRoute(); const router=useRouter(); const store=useTeacherStore(); const courseId=String(route.query.courseId ?? import.meta.env.VITE_DEFAULT_COURSE_ID ?? 'course-data-structures'); const profile=computed(()=>store.profile!); const caseId=computed(()=>store.workbench?.currentStudent?.demoCaseId ?? store.profile?.student.demoCaseId ?? null); const percent=(v:number)=>`${Math.round(v*100)}%`; const severityLabel=(v:string)=>({HIGH:'高关注',MEDIUM:'中关注',LOW:'低关注'}[v]??'待评估'); const formatDate=teacherTimestampLabel; async function load(){await store.loadProfile(String(route.params.studentId),courseId,true); if(!store.workbench) await store.loadWorkbench()}; onMounted(()=>void load())
</script>
